import java.util.*; 
public class PIEFLAVORED{
private static final long mod = 998244353;
   public static void main(String[] args) 
   {
      Scanner scanner = new Scanner(System.in);
      int n = scanner.nextInt();
      long kk = scanner.nextLong();
      if(kk >= n)
      {
         System.out.println("0");
      }
      else
      {
      int k = (int)(kk);
      int r = n - k;
      long[] rChoose = new long[r+1];
      rChoose[0] = 1L;
      long numerator = 1L;
      long denominator = 1L;
      for(int i = 1; i <= r; i++)
      {
         numerator = (numerator * (r + 1 - i)) % mod;
         denominator = (denominator * i) % mod;
         rChoose[i] = (numerator * power(denominator, mod - 2)) % mod;
      }
      long answer = 0;
      long sign = 1;
      for(int i = 0; i <= r; i++)
      {
         answer += power((long)(r - i), (long)(n)) * sign * rChoose[i];
         answer %= mod;
         sign = -sign;
      }
      answer = (answer * choose((long)n, (long)k)) % mod;
      if(k > 0)
      {
         answer = (answer * 2) % mod;
      }
      if(answer < 0)
      {
         answer += mod;
      }
      System.out.println("" + answer);
      }
   }
public static long choose(long n, long k)  
    { 
      long numerator = 1;
      long denominator = 1;
      for(int i = (int)(n - k + 1); i <= n; i++)
      {
         numerator = (numerator * i) % mod;
      } 
      for(int i = 1; i <= k; i++)
      {
         denominator = (denominator * i) % mod;
      } 
      denominator = power(denominator, mod - 2);
      return (numerator * denominator) % mod;
    } 
public static long power(long base, long exp) 
{ 
    long result = 1;      
    base = base % mod;
    while (exp > 0) 
    { 
        if ((exp & 1) == 1) 
        {    
            result = (result * base) % mod;
        }
        exp >>= 1;  
        base = (base * base) % mod; 
    } 
    return result; 
}
}
